"use client";

import * as React from "react";
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const Accordion = AccordionPrimitive.Root;

/** Firefly AccordionItem: one question, with a warm hairline under it and none under the last. */
const AccordionItem = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Item.Props>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    data-slot="accordion-item"
    className={cn("border-b border-border last:border-b-0", className)}
    {...props}
  />
));
AccordionItem.displayName = "AccordionItem";

/**
 * Firefly AccordionTrigger: the question in near-black at the base size,
 * underlined on hover. A muted chevron at the end turns over as the
 * answer opens.
 */
const AccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<AccordionPrimitive.Trigger.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Header data-slot="accordion-header" className="flex">
    <AccordionPrimitive.Trigger
      ref={ref}
      data-slot="accordion-trigger"
      className={cn(
        "group/trigger flex flex-1 items-center justify-between gap-3 rounded-md py-4 text-start",
        "text-base font-medium text-foreground underline-offset-4 hover:underline",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled) data-[disabled]:no-underline",
        className,
      )}
      {...props}
    >
      {children}
      <Icon
        icon="carbon:chevron-down"
        aria-hidden="true"
        className="size-4 shrink-0 text-muted-foreground transition-transform duration-fast ease-out group-data-[panel-open]/trigger:rotate-180"
      />
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = "AccordionTrigger";

/**
 * Firefly AccordionContent: the answer in secondary ink. The panel grows
 * to its measured height as it opens and folds back as it closes.
 */
const AccordionContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Panel.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Panel
    ref={ref}
    data-slot="accordion-content"
    className={cn(
      "h-(--accordion-panel-height) overflow-hidden text-sm text-(--foreground-secondary)",
      "transition-[height] duration-base ease-out",
      "data-[starting-style]:h-0 data-[ending-style]:h-0",
    )}
    {...props}
  >
    <div className={cn("pb-4", className)}>{children}</div>
  </AccordionPrimitive.Panel>
));
AccordionContent.displayName = "AccordionContent";

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };
